// Top navbar for the Before GPU Engineering notebook: chapter jumper with search, prev/next,
// reading progress, and visited / last-read marks kept in this browser only.
// Chapter list comes from chapters.js (generated by scripts/import_before_gpu.py).
(function () {
  const data = window.BGE;
  if (!data || !data.chapters) return;
  const chapters = data.chapters;
  const base = new URL(".", document.currentScript.src);    // the before-gpu/ folder
  const here = decodeURI(location.href.split(/[?#]/)[0].slice(base.href.length)) || "index.html";
  const idx = chapters.findIndex(c => c.href === here);
  const cur = idx >= 0 ? chapters[idx] : null;
  const url = c => new URL(c.href, base).href;

  const store = {
    get(key, fallback) {
      try { return JSON.parse(localStorage.getItem("bge:" + key)) ?? fallback; } catch { return fallback; }
    },
    set(key, value) {
      try { localStorage.setItem("bge:" + key, JSON.stringify(value)); } catch { /* private mode */ }
    },
  };
  const seen = new Set(store.get("seen", []));
  if (cur) {
    seen.add(cur.n);
    store.set("seen", [...seen]);
    store.set("last", cur.n);
  }

  const el = (tag, attrs = {}, ...kids) => {
    const node = document.createElement(tag);
    for (const [k, v] of Object.entries(attrs)) {
      if (k === "class") node.className = v;
      else if (k.startsWith("on")) node.addEventListener(k.slice(2), v);
      else if (v !== false && v != null) node.setAttribute(k, v === true ? "" : v);
    }
    node.append(...kids);
    return node;
  };

  // --- the bar ---
  const prev = idx > 0 ? chapters[idx - 1] : null;
  const next = cur ? chapters[idx + 1] : chapters[0];      // on the contents page, "next" starts chapter 1
  const navBtn = (c, label, title) => c
    ? el("a", { href: url(c), title: `${title}: Chapter ${c.n}, ${c.title}` }, label)
    : el("button", { disabled: true }, label);

  const jumpLabel = cur
    ? [el("b", {}, `ch ${cur.n}`), ` / ${chapters.length}`, el("span", { class: "bge-title" }, ` · ${cur.title}`), " ▾"]
    : [el("b", {}, "contents"), ` · ${chapters.length} chapters ▾`];
  const jump = el("button", { class: "bge-jump", "aria-expanded": "false", "aria-controls": "bge-panel",
                              title: "Jump to a chapter (/)" }, ...jumpLabel);
  const filter = el("input", { type: "search", placeholder: "filter chapters: number, title or part…",
                               "aria-label": "Filter chapters" });
  const list = el("div", { class: "bge-list" });
  const panel = el("div", { class: "bge-panel", id: "bge-panel", hidden: true }, filter, list);
  const progress = el("div", { class: "bge-progress" });

  const bar = el("nav", { class: "bge-bar", "aria-label": "Notebook" },
    el("a", { class: "bge-brand", href: base.href, title: "Contents" },
      el("span", { class: "bge-mark" }, "bge"), el("span", { class: "bge-long" }, " before gpu engineering")),
    el("div", { class: "bge-jump-wrap" }, jump, panel),
    el("div", { class: "bge-side" },
      navBtn(prev, "← prev", "Previous"),
      navBtn(next, "next →", "Next"),
      el("a", { class: "bge-ext bge-wide", href: new URL("../", base).href, title: "GPU Codes home" }, "gpu codes"),
      el("a", { class: "bge-ext bge-wide", href: data.upstream, target: "_blank", rel: "noopener",
                title: "Original repository" }, "source ↗")),
    progress);
  document.body.prepend(bar);

  // --- chapter panel ---
  function render(query) {
    const q = query.trim().toLowerCase();
    list.replaceChildren();
    let phase, part, hits = 0;
    for (const c of chapters) {
      const hay = `${c.n} ${c.title} ${c.part} ${c.phase}`.toLowerCase();
      if (q && !q.split(/\s+/).every(w => hay.includes(w))) continue;
      if (c.phase !== phase) list.append(el("h4", {}, (phase = c.phase).toLowerCase()));
      if (c.part !== part) list.append(el("h5", {}, (part = c.part)));
      list.append(el("a", { href: url(c), class: c === cur ? "bge-current" : "",
                            "aria-current": c === cur ? "page" : false },
        el("span", { class: "bge-n" }, String(c.n)), el("span", {}, c.title),
        seen.has(c.n) ? el("span", { class: "bge-seen", title: "read" }, "✓") : ""));
      hits++;
    }
    if (!hits) list.append(el("div", { class: "bge-empty" }, "no chapter matches"));
  }

  function toggle(open) {
    panel.hidden = !open;
    jump.setAttribute("aria-expanded", String(open));
    if (open) {
      filter.value = "";
      render("");
      filter.focus();
      list.querySelector(".bge-current")?.scrollIntoView({ block: "center" });
    }
  }

  jump.addEventListener("click", () => toggle(panel.hidden));
  filter.addEventListener("input", () => render(filter.value));
  filter.addEventListener("keydown", e => {
    if (e.key === "Enter") list.querySelector("a")?.click();
  });
  document.addEventListener("click", e => {
    if (!panel.hidden && !bar.contains(e.target)) toggle(false);
  });

  // --- keyboard: ← → page, / opens the jumper, Esc closes it ---
  document.addEventListener("keydown", e => {
    if (e.key === "Escape" && !panel.hidden) { toggle(false); jump.focus(); return; }
    const typing = /^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName) || e.target.isContentEditable;
    if (typing || e.metaKey || e.ctrlKey || e.altKey) return;
    if (e.key === "/") { e.preventDefault(); toggle(true); }
    else if (e.key === "ArrowLeft" && prev) location.href = url(prev);
    else if (e.key === "ArrowRight" && next) location.href = url(next);
  });

  // --- reading progress ---
  const onScroll = () => {
    const max = document.documentElement.scrollHeight - innerHeight;
    progress.style.width = max > 0 ? `${Math.min(100, (scrollY / max) * 100)}%` : "0";
  };
  addEventListener("scroll", onScroll, { passive: true });
  addEventListener("resize", onScroll);
  onScroll();

  // --- contents page: mark read chapters, offer to continue ---
  if (!cur) {
    for (const a of document.querySelectorAll(".notebook-grid-content a[href]")) {
      const c = chapters.find(ch => ch.href === a.getAttribute("href"));
      if (c && seen.has(c.n)) a.append(el("span", { class: "text-green", title: "read" }, " ✓"));
    }
    const last = chapters.find(c => c.n === store.get("last", null));
    const h1 = document.querySelector(".notebook-grid-content h1");
    if (last && h1) {
      h1.after(el("div", { class: "bge-continue" },
        "↳ continue: ", el("a", { href: url(last) }, `Chapter ${last.n}, ${last.title}`),
        ` · ${seen.size} / ${chapters.length} read`));
    }
  }

  // --- credit (the MIT license asks that the notice travel with the copy) ---
  const wrapper = document.querySelector(".notebook-wrapper");
  if (wrapper) {
    wrapper.append(el("p", { class: "bge-credit" },
      "Before GPU Engineering © 2026 Ranjan Yadav · ",
      el("a", { href: new URL("LICENSE", base).href }, "MIT license"), " · ",
      el("a", { href: data.upstream, target: "_blank", rel: "noopener" }, "original repository")));
  }
})();
